struct C2DVector { float X, Y; }; enum EInputDeviceType { INPUT_DEVICE_JOYSTICK = 1 }; enum EInputEventType { INPUT_EVENT_JOYSTICK_POSITION = 0x11 }; struct CInputEventRetail { C2DVector Position; unsigned char DataRemainder[0x18]; EInputDeviceType DeviceType; long DeviceNumber; EInputEventType Type; float CurrentTime; float StartTime; void SetAsJoystickPosition(const C2DVector& position, double time); }; void CInputEventRetail::SetAsJoystickPosition(const C2DVector& position, double time) { DeviceType = INPUT_DEVICE_JOYSTICK; Type = INPUT_EVENT_JOYSTICK_POSITION; Position.X = position.X; Position.Y = position.Y; StartTime = (float)time; CurrentTime = (float)time; }